const money = (value: number) =>
  new Intl.NumberFormat("nl-BE", {
    style: "currency",
    currency: "EUR",
    maximumFractionDigits: 0,
  }).format(value);

const number = (value: number) =>
  new Intl.NumberFormat("nl-BE", { maximumFractionDigits: 2 }).format(value);

const employeeFullName = (employee: Employee) =>
  `${employee.firstName} ${employee.lastName}`.trim();

const employeeByName = (employees: Employee[], name?: string) => {
  const normalized = name?.trim().toLocaleLowerCase();
  return normalized
    ? employees.find(
        (employee) => employeeFullName(employee).toLocaleLowerCase() === normalized,
      )
    : undefined;
};

function HrEmployeeSelect({
  employees,
  value,
  fallbackName,
  onChange,
  placeholder = "Selecteer uit HR",
  required = false,
  ariaLabel,
}: {
  employees: Employee[];
  value?: string;
  fallbackName?: string;
  onChange: (employee: Employee | undefined) => void;
  placeholder?: string;
  required?: boolean;
  ariaLabel?: string;
}) {
  const activeEmployees = employees.filter((employee) => employee.active);
  const linkedEmployee = activeEmployees.find((employee) => employee.id === value)
    ?? employeeByName(activeEmployees, fallbackName);
  const suggestionListId = useRef(`employee-suggestions-${createId()}`);
  const linkedName = linkedEmployee ? employeeFullName(linkedEmployee) : fallbackName ?? "";
  const [searchValue, setSearchValue] = useState(linkedName);
  useEffect(() => setSearchValue(linkedName), [linkedName]);
  const exactEmployee = (text: string) => activeEmployees.find(
    (employee) => employeeFullName(employee).toLocaleLowerCase() === text.trim().toLocaleLowerCase(),
  );
  return (
    <span className="employee-autocomplete">
      <Search size={14}/>
      <input
        type="text"
        list={suggestionListId.current}
        aria-label={ariaLabel}
        autoComplete="off"
        required={required}
        placeholder={fallbackName && !linkedEmployee ? `${fallbackName} (niet gekoppeld)` : placeholder}
        value={searchValue}
        onChange={(event) => {
          const next = event.target.value;
          setSearchValue(next);
          const exact = exactEmployee(next);
          if (exact) onChange(exact);
          else if (!next.trim()) onChange(undefined);
        }}
        onBlur={() => {
          const exact = exactEmployee(searchValue);
          if (exact) {
            setSearchValue(employeeFullName(exact));
            onChange(exact);
          } else {
            setSearchValue(linkedName);
            if (!linkedName) onChange(undefined);
          }
        }}
      />
      <ChevronDown size={13}/>
      <datalist id={suggestionListId.current}>
        {activeEmployees.map((employee) => (
          <option key={employee.id} value={employeeFullName(employee)} label={employee.role}/>
        ))}
      </datalist>
    </span>
  );
}

type TablePreference = {
  order: string[];
  widths: Record<string, number>;
  filters: Record<string, string>;
  sort?: { key: string; direction: "asc" | "desc" };
};

const dutchTableMonths = ["jan", "feb", "mrt", "apr", "mei", "jun", "jul", "aug", "sep", "okt", "nov", "dec"];
const tableCollator = new Intl.Collator("nl-BE", { numeric: true, sensitivity: "base" });

const tableSortValue = (text: string): string | number => {
  const value = text.replace(/\s+/g, " ").trim();
  const dateMatch = value.toLocaleLowerCase().match(/^(\d{1,2})\s+([a-z]{3})\s+(\d{4})$/);
  if (dateMatch) {
    const month = dutchTableMonths.indexOf(dateMatch[2]);
    if (month >= 0) return Date.UTC(Number(dateMatch[3]), month, Number(dateMatch[1]));
  }
  if (/^[\s€$£\d.,%+-]+$/.test(value) && /\d/.test(value)) {
    const normalized = value.replace(/[^\d,.\-+]/g, "").replace(/\.(?=\d{3}(?:\D|$))/g, "").replace(",", ".");
    const number = Number(normalized);
    if (Number.isFinite(number)) return number;
  }
  return value;
};

const compareTableText = (left: string, right: string) => {
  const leftValue = tableSortValue(left);
  const rightValue = tableSortValue(right);
  if (typeof leftValue === "number" && typeof rightValue === "number") return leftValue - rightValue;
  return tableCollator.compare(String(leftValue), String(rightValue));
};

type CalculationTransferPayload =
  | { type: "library-item"; itemIds: string[]; label: string }
  | { type: "library-group"; itemIds: string[]; code: string; label: string }
  | { type: "calculation-items"; sourceCalculationId: string; itemIds: string[]; label: string }
  | { type: "calculation-chapter"; sourceCalculationId: string; chapterId: string; label: string }
  | { type: "calculation-template"; templateId: string; label: string };

type CalculationIssue = {
  id: string;
  severity: "Kritiek" | "Waarschuwing" | "Info";
  title: string;
  detail: string;
  itemId?: string;
};

const calculationQualityIssues = (calculation: Calculation, library: CostLibraryItem[]): CalculationIssue[] => {
  const issues: CalculationIssue[] = [];
  const duplicateCodes = new Set<string>();
  const seenCodes = new Set<string>();
  calculation.items.forEach(item => {
    if (seenCodes.has(item.code)) duplicateCodes.add(item.code);
    seenCodes.add(item.code);
    const effective = effectiveBoqValues(item);
    const formulaError = Object.values(effective.errors).find(Boolean);
    if (formulaError) issues.push({ id: `formula-${item.id}`, severity: "Kritiek", title: `${item.code} · formulefout`, detail: formulaError, itemId: item.id });
    if (boqItemQuantity(item) <= 0 && !["Tekstregel", "Subtotaal"].includes(item.postType ?? "")) issues.push({ id: `quantity-${item.id}`, severity: "Waarschuwing", title: `${item.code} · hoeveelheid ontbreekt`, detail: "Vul een positieve hoeveelheid in of gebruik een niet-prijsdragend posttype.", itemId: item.id });
    if (unitCost(item) <= 0 && !["Tekstregel", "Subtotaal"].includes(item.postType ?? "")) issues.push({ id: `cost-${item.id}`, severity: "Kritiek", title: `${item.code} · geen kostprijs`, detail: "Deze prijsdragende post heeft geen arbeid, materiaal, materieel of onderaanneming.", itemId: item.id });
    const linkedIds = Object.values(item.costApplications ?? {}).flatMap(application => application?.libraryItemId ? [application.libraryItemId] : []);
    linkedIds.forEach(libraryItemId => {
      const source = library.find(entry => entry.id === libraryItemId);
      if (!source) issues.push({ id: `source-${item.id}-${libraryItemId}`, severity: "Waarschuwing", title: `${item.code} · prijsbron ontbreekt`, detail: "De gekoppelde bibliotheekregel is niet langer beschikbaar.", itemId: item.id });
      else if (Date.now() - new Date(source.updatedAt).getTime() > 365 * 86_400_000) issues.push({ id: `stale-${item.id}-${libraryItemId}`, severity: "Info", title: `${item.code} · prijs ouder dan één jaar`, detail: `${source.code} werd voor het laatst bijgewerkt op ${date(source.updatedAt)}.`, itemId: item.id });
    });
  });
  duplicateCodes.forEach(code => issues.push({ id: `duplicate-${code}`, severity: "Waarschuwing", title: `${code} · dubbele postcode`, detail: "Controleer of deze posten bewust dezelfde code gebruiken." }));
  if (!calculation.chapters.length) issues.push({ id: "structure", severity: "Info", title: "Geen hoofdstukstructuur", detail: "Gebruik hoofdstukken om grote meetstaten beheersbaar te houden." });
  return issues;
};

const writeCalculationTransfer = (event: DragEvent<HTMLElement>, payload: CalculationTransferPayload) => {
  event.dataTransfer.effectAllowed = "copy";
  event.dataTransfer.setData("application/x-bouwflow-calculation", JSON.stringify(payload));
  event.dataTransfer.setData("text/plain", payload.label);
};

const readCalculationTransfer = (event: DragEvent<HTMLElement>): CalculationTransferPayload | undefined => {
  try {
    const value = event.dataTransfer.getData("application/x-bouwflow-calculation");
    return value ? JSON.parse(value) as CalculationTransferPayload : undefined;
  } catch {
    return undefined;
  }
};

function usePersonalizedTables(
  containerRef: { current: HTMLElement | null },
  page: Page,
  userKey: string,
  globalFilter: string,
  loadRemote?: (key: string) => Promise<TablePreference | undefined>,
  saveRemote?: (key: string, value: TablePreference) => Promise<void>,
) {
  useEffect(() => {
    const container = containerRef.current;
    if (!container || typeof window === "undefined") return;
    container.dataset.tableGlobalFilter = globalFilter;
    let active = true;
    let scheduled = false;

    const enhance = () => {
      scheduled = false;
      container.querySelectorAll<HTMLTableElement>("table").forEach((table, tableIndex) => {
        const headerRow = table.tHead?.rows[0];
        const bodyRows = Array.from(table.tBodies).flatMap((body) => Array.from(body.rows));
        if (!headerRow || headerRow.cells.length < 2 || !bodyRows.every((row) => row.cells.length === headerRow.cells.length)) return;
        const headers = Array.from(headerRow.cells) as HTMLTableCellElement[];
        headers.forEach((header, index) => {
          if (!header.dataset.columnKey) {
            header.dataset.columnLabel = (header.textContent ?? "").trim() || `Kolom ${index + 1}`;
            const label = header.dataset.columnLabel.toLocaleLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
            header.dataset.columnKey = label || `kolom-${index + 1}`;
          }
        });
        const signature = headers.map((header) => header.dataset.columnKey).join(".");
        const storageKey = `bouwflow-table-v1:${userKey}:${page}:${tableIndex}:${signature}`;
        const preferenceKey = `table-v1:${page}:${tableIndex}:${signature}`;
        const defaults: TablePreference = { order: headers.map((header) => header.dataset.columnKey!), widths: {}, filters: {} };
        let preference = defaults;
        try {
          preference = { ...defaults, ...JSON.parse(localStorage.getItem(storageKey) ?? "{}") };
        } catch {
          preference = defaults;
        }
        const knownKeys = new Set(defaults.order);
        preference.order = [...preference.order.filter((key) => knownKeys.has(key)), ...defaults.order.filter((key) => !preference.order.includes(key))];
        if (preference.sort && !knownKeys.has(preference.sort.key)) preference.sort = undefined;

        const save = () => {
          localStorage.setItem(storageKey, JSON.stringify(preference));
          if (saveRemote) void saveRemote(preferenceKey, preference);
        };
        const apply = () => {
          const columns = preference.order.map((key) => `${Math.max(90, preference.widths[key] ?? (key.startsWith("kolom-") ? 100 : 160))}px`).join(" ");
          table.classList.add("personalized-table");
          [headerRow, ...bodyRows].forEach((row) => {
            row.style.gridTemplateColumns = columns;
            Array.from(row.cells).forEach((cell, originalIndex) => {
              const key = headers[originalIndex]?.dataset.columnKey;
              if (key) {
                const element = cell as HTMLElement;
                element.style.gridColumn = String(preference.order.indexOf(key) + 1);
                element.style.gridRow = "1";
              }
            });
          });
          const sortIndex = preference.sort ? headers.findIndex(header => header.dataset.columnKey === preference.sort?.key) : -1;
          const orderedRows = bodyRows.map((row, index) => ({ row, index }));
          if (sortIndex >= 0 && preference.sort) {
            const direction = preference.sort.direction === "asc" ? 1 : -1;
            orderedRows.sort((left, right) => {
              const comparison = compareTableText(left.row.cells[sortIndex]?.textContent ?? "", right.row.cells[sortIndex]?.textContent ?? "");
              return comparison ? comparison * direction : left.index - right.index;
            });
          }
          orderedRows.forEach(({ row }, index) => {
            row.style.order = String(index);
          });
          bodyRows.forEach((row) => {
            const normalizedGlobalFilter = (container.dataset.tableGlobalFilter ?? "").trim().toLocaleLowerCase();
            const visibleOnPage = !normalizedGlobalFilter || (row.textContent ?? "").toLocaleLowerCase().includes(normalizedGlobalFilter);
            const visible = visibleOnPage && headers.every((header, index) => {
              const key = header.dataset.columnKey!;
              const filter = (preference.filters[key] ?? "").trim().toLocaleLowerCase();
              return !filter || (row.cells[index]?.textContent ?? "").toLocaleLowerCase().includes(filter);
            });
            row.classList.toggle("table-row-filtered", !visible);
          });
          headers.forEach(header => {
            const key = header.dataset.columnKey!;
            const sortButton = header.querySelector<HTMLButtonElement>(":scope > .table-column-tools > .table-column-sort");
            if (!sortButton) return;
            const direction = preference.sort?.key === key ? preference.sort.direction : undefined;
            sortButton.textContent = direction === "asc" ? "↑" : direction === "desc" ? "↓" : "↕";
            sortButton.classList.toggle("active", Boolean(direction));
            const label = header.dataset.columnLabel || key;
            sortButton.setAttribute("aria-label", direction === "asc" ? `Sorteer ${label} aflopend` : direction === "desc" ? `Sortering ${label} wissen` : `Sorteer ${label} oplopend`);
            sortButton.title = direction === "asc" ? "Oplopend · klik voor aflopend" : direction === "desc" ? "Aflopend · klik om sortering te wissen" : "Klik om oplopend te sorteren";
          });
        };

        headers.forEach((header) => {
          const key = header.dataset.columnKey!;
          if (!header.querySelector(":scope > .table-column-tools")) {
            const tools = document.createElement("span");
            tools.className = "table-column-tools";
            const filter = document.createElement("input");
            filter.type = "search";
            filter.value = preference.filters[key] ?? "";
            filter.placeholder = "Filter";
            filter.setAttribute("aria-label", `Filter ${header.textContent?.trim() || key}`);
            filter.addEventListener("input", () => {
              preference.filters[key] = filter.value;
              save();
              apply();
            });
            filter.addEventListener("pointerdown", (event) => event.stopPropagation());
            const sortButton = document.createElement("button");
            sortButton.type = "button";
            sortButton.className = "table-column-sort";
            sortButton.textContent = "↕";
            sortButton.addEventListener("pointerdown", (event) => event.stopPropagation());
            sortButton.addEventListener("click", (event) => {
              event.preventDefault();
              event.stopPropagation();
              const current = preference.sort?.key === key ? preference.sort.direction : undefined;
              preference.sort = current === "asc" ? { key, direction: "desc" } : current === "desc" ? undefined : { key, direction: "asc" };
              save();
              apply();
            });
            const resizer = document.createElement("i");
            resizer.className = "table-column-resizer";
            resizer.title = "Sleep om kolombreedte aan te passen";
            resizer.addEventListener("pointerdown", (event) => {
              event.preventDefault();
              event.stopPropagation();
              const startX = event.clientX;
              const startWidth = preference.widths[key] ?? header.getBoundingClientRect().width;
              const move = (moveEvent: PointerEvent) => {
                preference.widths[key] = Math.max(90, Math.round(startWidth + moveEvent.clientX - startX));
                apply();
              };
              const up = () => {
                save();
                window.removeEventListener("pointermove", move);
                window.removeEventListener("pointerup", up);
              };
              window.addEventListener("pointermove", move);
              window.addEventListener("pointerup", up);
            });
            tools.append(filter, sortButton, resizer);
            header.append(tools);
          }
          header.draggable = true;
          header.title = "Sleep om kolom te verplaatsen";
          if (!header.dataset.dragReady) {
            header.dataset.dragReady = "true";
            header.addEventListener("dragstart", (event) => event.dataTransfer?.setData("text/bouwflow-column", key));
          }
          if (!header.dataset.dropReady) {
            header.dataset.dropReady = "true";
            header.addEventListener("dragover", (event) => event.preventDefault());
            header.addEventListener("drop", (event) => {
              event.preventDefault();
              const source = event.dataTransfer?.getData("text/bouwflow-column");
              if (!source || source === key || !preference.order.includes(source)) return;
              const next = preference.order.filter((item) => item !== source);
              next.splice(next.indexOf(key), 0, source);
              preference.order = next;
              save();
              apply();
            });
          }
        });
        apply();
        if (loadRemote && table.dataset.remotePreferenceKey !== preferenceKey) {
          table.dataset.remotePreferenceKey = preferenceKey;
          void loadRemote(preferenceKey).then((remotePreference) => {
            if (!active || !remotePreference) return;
            preference = { ...defaults, ...remotePreference };
            preference.order = [...preference.order.filter((key) => knownKeys.has(key)), ...defaults.order.filter((key) => !preference.order.includes(key))];
            if (preference.sort && !knownKeys.has(preference.sort.key)) preference.sort = undefined;
            localStorage.setItem(storageKey, JSON.stringify(preference));
            apply();
          });
        }
      });
    };

    const schedule = () => {
      if (scheduled) return;
      scheduled = true;
      window.requestAnimationFrame(enhance);
    };
    schedule();
    const observer = new MutationObserver(schedule);
    observer.observe(container, { childList: true, subtree: true });
    return () => {
      active = false;
      observer.disconnect();
    };
  }, [containerRef, globalFilter, loadRemote, page, saveRemote, userKey]);
}
const price = (value: number) =>
  new Intl.NumberFormat("nl-BE", {
    style: "currency",
    currency: "EUR",
    minimumFractionDigits: 2,
    maximumFractionDigits: 4,
  }).format(value);
