function DocumentDetailDialog({ document, onClose }: { document: ProjectDocument; onClose: () => void }) {
  const current = document.versions.find((version) => version.id === document.currentVersionId) ?? document.versions[0];
  const events: RecordTimelineEvent[] = [
    ...document.versions.map((version) => ({ label: `${version.revisionLabel} geüpload`, at: version.createdAt, actor: version.uploadedBy, detail: version.notes || version.fileName })),
    { label: "Goedgekeurd", at: document.approvedAt, actor: document.approvedBy },
    ...document.recipients.map((recipient) => ({ label: `Verzonden naar ${recipient.name}`, at: recipient.deliveredAt, detail: recipient.email })),
    ...document.recipients.filter((recipient) => recipient.readAt).map((recipient) => ({ label: `Gelezen door ${recipient.name}`, at: recipient.readAt, detail: recipient.email })),
  ].sort((left, right) => (left.at ?? "").localeCompare(right.at ?? ""));
  return <div className="modal-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="modal record-detail-modal"><div className="modal-head"><div><p className="eyebrow">{document.category} · {current?.revisionLabel}</p><h2>{document.title}</h2></div><button className="icon-button" aria-label="Sluiten" onClick={onClose}><X size={20}/></button></div><div className="record-detail-content"><section className="record-detail-summary"><div><span>Status</span><Badge text={document.status}/></div><div><span>Actuele versie</span><strong>{current?.revisionLabel ?? "—"}</strong></div><div><span>Revisies</span><strong>{document.versions.length}</strong></div><div><span>Ontvangers</span><strong>{document.recipients.length}</strong></div></section><div className="record-detail-grid"><section><h3>Versies</h3><div className="detail-line-list">{document.versions.map((version) => <div key={version.id}><strong>{version.revisionLabel} · {version.fileName}</strong><span>{dateTime(version.createdAt)} · {version.uploadedBy} · {fileSize(version.sizeBytes)}</span></div>)}</div><h3>Distributie</h3><div className="detail-line-list">{document.recipients.map((recipient) => <div key={recipient.id}><strong>{recipient.name}</strong><span>{recipient.email} · {recipient.readAt ? `gelezen ${dateTime(recipient.readAt)}` : "nog niet gelezen"}</span></div>)}</div></section><section><h3>Statushistoriek</h3><RecordTimeline events={events}/></section></div></div><div className="modal-actions"><button className="primary" onClick={onClose}>Sluiten</button></div></div></div>;
}

